<?php require_once __DIR__.'/../config/auth.php';require_login();$id=user()['id'];$s=db()->prepare("SELECT e.*,l.titulo,l.autor FROM emprestimos e JOIN livros l ON l.id=e.livro_id WHERE e.usuario_id=? ORDER BY e.created_at DESC");$s->execute([$id]);$loans=$s->fetchAll();$active=array_filter($loans,fn($x)=>in_array(loan_status($x),['ativo','atrasado']));$late=array_filter($loans,fn($x)=>loan_status($x)==='atrasado');$pageTitle='Olá, '.explode(' ',user()['nome'])[0];require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><div class="dashboard-cards"><div class="card metric"><span>Empréstimos ativos</span><b><?=count($active)?></b></div><div class="card metric"><span>Devoluções no histórico</span><b><?=count(array_filter($loans,fn($x)=>$x['status']==='devolvido'))?></b></div><div class="card metric"><span>Pendências</span><b><?=count($late)?></b></div></div><section class="panel"><h2>Seus empréstimos recentes</h2><div class="table-wrap"><table><thead><tr><th>Livro</th><th>Retirada</th><th>Devolução prevista</th><th>Status</th></tr></thead><tbody><?php foreach(array_slice($loans,0,5) as $l):$status=loan_status($l)?><tr><td><b><?=e($l['titulo'])?></b><br><small><?=e($l['autor'])?></small></td><td><?=date('d/m/Y',strtotime($l['data_emprestimo']))?></td><td><?=date('d/m/Y',strtotime($l['data_prevista_devolucao']))?></td><td><span class="badge <?=$status==='atrasado'?'off':''?>"><?=e(ucfirst($status))?></span></td></tr><?php endforeach;?><?php if(!$loans):?><tr><td colspan="4" class="empty">Você ainda não possui empréstimos.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/dashboard-footer.php';?>
